const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Restaurant dining table booking optimizer. Predicts no-show likelihood based on party size, reservation lead time, and peak hour slots; calculates optimal table turnaround and auto-release thresholds.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"restaurantId":"REST-102","restaurantName":"The Bistro Club","reservationId":"RES-882","partySize":6,"slotTime":"20:00","turnaroundEstimateMinutes":75,"noShowRisk":"LOW","noShowProbability":8.5,"tableAllocationRecommendation":"Table 14 (Family Booth, 6-8 seats)","waitlistAutoReleaseMinutes":15,"yieldAdvice":"High dinner demand: release unconfirmed reservations at 20:15 to walk-in waitlist."}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"restaurantId":"REST-102","restaurantName":"The Bistro Club","reservationId":"RES-882","partySize":6,"slotTime":"20:00","turnaroundEstimateMinutes":75,"noShowRisk":"LOW","noShowProbability":8.5,"tableAllocationRecommendation":"Table 14 (Family Booth, 6-8 seats)","waitlistAutoReleaseMinutes":15,"yieldAdvice":"High dinner demand: release unconfirmed reservations at 20:15 to walk-in waitlist."} } }];
}
